{"filePath":"我的博客目录/script.js","content":"// 移动端菜单切换
function toggleMenu() {
    const navLinks = document.getElementById('navLinks');
    navLinks.classList.toggle('active');
}

// 导航栏滚动效果
let lastScroll = 0;
window.addEventListener('scroll', () => {
    const navbar = document.querySelector('.navbar');
    const currentScroll = window.pageYOffset;

    if (currentScroll > lastScroll && currentScroll > 100) {
        navbar.style.transform = 'translateX(-50%) translateY(-150%)';
    } else {
        navbar.style.transform = 'translateX(-50%) translateY(0)';
    }

    lastScroll = currentScroll;
});

// 滚动动画
const observerOptions = {
    threshold: 0.1,
    rootMargin: '0px 0px -50px 0px'
};

const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            entry.target.classList.add('visible');
        }
    });
}, observerOptions);

document.querySelectorAll('.fade-in').forEach(el => {
    observer.observe(el);
});

// 平滑滚动
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function(e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
            target.scrollIntoView({
                behavior: 'smooth',
                block: 'start'
            });

            // 关闭移动端菜单
            const navLinks = document.getElementById('navLinks');
            if (navLinks.classList.contains('active')) {
                navLinks.classList.remove('active');
            }
        }
    });
});

// 点击外部关闭移动端菜单
document.addEventListener('click', (e) => {
    const navLinks = document.getElementById('navLinks');
    const mobileMenuBtn = document.querySelector('.mobile-menu-btn');

    if (!navLinks.contains(e.target) && !mobileMenuBtn.contains(e.target) && navLinks.classList.contains('active')) {
        navLinks.classList.remove('active');
    }
});

// 文章卡片悬停效果增强
document.querySelectorAll('.article-card, .article-item, .related-card').forEach(card => {
    card.addEventListener('mouseenter', function() {
        this.style.transform = 'translateY(-8px)';
    });

    card.addEventListener('mouseleave', function() {
        this.style.transform = 'translateY(0)';
    });
});

// 技能标签随机动画
document.querySelectorAll('.skill-tag, .skill-item').forEach((tag, index) => {
    tag.style.animationDelay = `${index * 0.1}s`;
});

// 页面加载动画
window.addEventListener('load', () => {
    document.body.style.opacity = '0';
    document.body.style.transition = 'opacity 0.5s ease';

    setTimeout(() => {
        document.body.style.opacity = '1';
    }, 100);
});

// 返回顶部按钮
const createBackToTopButton = () => {
    const button = document.createElement('button');
    button.innerHTML = `
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <polyline points="18 15 12 9 6 15"></polyline>
        </svg>
    `;
    button.style.cssText = `
        position: fixed;
        bottom: 2rem;
        right: 2rem;
        width: 50px;
        height: 50px;
        background: linear-gradient(135deg, var(--primary), var(--secondary));
        border: none;
        border-radius: 50%;
        color: white;
        cursor: pointer;
        opacity: 0;
        visibility: hidden;
        transform: translateY(20px);
        transition: all 0.3s ease;
        z-index: 999;
        box-shadow: 0 4px 20px rgba(99, 102, 241, 0.4);
    `;

    button.addEventListener('click', () => {
        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    });

    document.body.appendChild(button);

    window.addEventListener('scroll', () => {
        if (window.pageYOffset > 500) {
            button.style.opacity = '1';
            button.style.visibility = 'visible';
            button.style.transform = 'translateY(0)';
        } else {
            button.style.opacity = '0';
            button.style.visibility = 'hidden';
            button.style.transform = 'translateY(20px)';
        }
    });
};

// 初始化返回顶部按钮
createBackToTopButton();

// 文章目录高亮当前章节
const updateActiveToc = () => {
    const headings = document.querySelectorAll('.article-content h2, .article-content h3');
    const tocLinks = document.querySelectorAll('.toc a');

    let currentHeading = null;

    headings.forEach(heading => {
        const rect = heading.getBoundingClientRect();
        if (rect.top <= 200) {
            currentHeading = heading;
        }
    });

    if (currentHeading) {
        const id = currentHeading.id;
        tocLinks.forEach(link => {
            if (link.getAttribute('href') === `#${id}`) {
                link.style.color = 'var(--primary)';
                link.style.fontWeight = '600';
            } else {
                link.style.color = 'var(--text-secondary)';
                link.style.fontWeight = 'normal';
            }
        });
    }
};

// 监听滚动以更新目录高亮
if (document.querySelector('.toc')) {
    window.addEventListener('scroll', updateActiveToc);
}

// 复制代码块功能
document.querySelectorAll('pre code').forEach(block => {
    const pre = block.parentElement;

    const copyButton = document.createElement('button');
    copyButton.innerHTML = '复制';
    copyButton.style.cssText = `
        position: absolute;
        top: 0.75rem;
        right: 0.75rem;
        padding: 0.4rem 0.8rem;
        background: var(--bg-tertiary);
        border: 1px solid var(--border-color);
        border-radius: 6px;
        color: var(--text-secondary);
        font-size: 0.85rem;
        cursor: pointer;
        transition: all 0.3s ease;
    `;

    pre.style.position = 'relative';
    pre.appendChild(copyButton);

    copyButton.addEventListener('click', async () => {
        try {
            await navigator.clipboard.writeText(block.textContent);
            copyButton.innerHTML = '已复制!';
            copyButton.style.background = 'var(--primary)';
            copyButton.style.color = 'white';

            setTimeout(() => {
                copyButton.innerHTML = '复制';
                copyButton.style.background = 'var(--bg-tertiary)';
                copyButton.style.color = 'var(--text-secondary)';
            }, 2000);
        } catch (err) {
            console.error('复制失败:', err);
        }
    });
});

// 搜索功能（简单实现）
const searchInput = document.querySelector('input[type="search"]');
if (searchInput) {
    let searchTimeout;

    searchInput.addEventListener('input', (e) => {
        clearTimeout(searchTimeout);
        const query = e.target.value.toLowerCase();

        searchTimeout = setTimeout(() => {
            document.querySelectorAll('.article-item').forEach(article => {
                const title = article.querySelector('.article-title').textContent.toLowerCase();
                const summary = article.querySelector('.article-summary').textContent.toLowerCase();

                if (title.includes(query) || summary.includes(query)) {
                    article.style.display = 'flex';
                } else {
                    article.style.display = 'none';
                }
            });
        }, 300);
    });
}

// 阅读进度条
const createProgressBar = () => {
    const progressBar = document.createElement('div');
    progressBar.style.cssText = `
        position: fixed;
        top: 0;
        left: 0;
        width: 0%;
        height: 3px;
        background: linear-gradient(90deg, var(--primary), var(--secondary));
        z-index: 10000;
        transition: width 0.1s ease;
    `;

    document.body.appendChild(progressBar);

    window.addEventListener('scroll', () => {
        const scrollTop = window.pageYOffset;
        const docHeight = document.documentElement.scrollHeight - window.innerHeight;
        const progress = (scrollTop / docHeight) * 100;
        progressBar.style.width = `${progress}%`;
    });
};

// 仅在文章详情页显示进度条
if (document.querySelector('.article-content')) {
    createProgressBar();
}

// 图片懒加载
if ('IntersectionObserver' in window) {
    const imageObserver = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                const img = entry.target;
                img.src = img.dataset.src || img.src;
                img.classList.add('loaded');
                observer.unobserve(img);
            }
        });
    });

    document.querySelectorAll('img[data-src]').forEach(img => {
        imageObserver.observe(img);
    });
}

// 键盘快捷键
document.addEventListener('keydown', (e) => {
    // 按 ESC 关闭移动端菜单
    if (e.key === 'Escape') {
        const navLinks = document.getElementById('navLinks');
        if (navLinks.classList.contains('active')) {
            navLinks.classList.remove('active');
        }
    }

    // 按 / 聚焦搜索框（如果有）
    if (e.key === '/' && document.activeElement.tagName !== 'INPUT' && document.activeElement.tagName !== 'TEXTAREA') {
        const searchInput = document.querySelector('input[type="search"]');
        if (searchInput) {
            e.preventDefault();
            searchInput.focus();
        }
    }
});

// 控制台欢迎信息
console.log('%c欢迎访问我的博客！', 'color: #6366f1; font-size: 20px; font-weight: bold;');
console.log('%c如果你对代码感兴趣，可以查看 GitHub 仓库。', 'color: #cbd5e1; font-size: 14px;');

// 性能优化：防抖函数
function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
        const later = () => {
            clearTimeout(timeout);
            func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
    };
}

// 性能优化：节流函数
function throttle(func, limit) {
    let inThrottle;
    return function(...args) {
        if (!inThrottle) {
            func.apply(this, args);
            inThrottle = true;
            setTimeout(() => inThrottle = false, limit);
        }
    };
}

// 应用节流到滚动事件
const throttledScroll = throttle(() => {
    // 滚动相关的处理逻辑
}, 100);

window.addEventListener('scroll', throttledScroll);
"}

